mapper.update:
UPDATE ai_training_plans
SET review_status = #{status},
    reviewer_id = #{reviewerId},
    reviewed_at = NOW(),
    review_comment = #{comment}
WHERE id = #{planId}

mapper.delete:
DELETE FROM ai_training_plans
WHERE student_id = #{studentId}
  AND created_at >= (SELECT MIN(sub.created_at) FROM (
      SELECT created_at FROM ai_training_plans WHERE id = #{planGroupId} AND student_id = #{studentId}
  ) sub)
  AND created_at <= (SELECT MAX(sub.created_at) FROM (
      SELECT created_at FROM ai_training_plans WHERE id = #{planGroupId} AND student_id = #{studentId}
  ) sub)
